/*!
 * AdminLTE.js - versi ringkas dan readable
 * Fungsi: Sidebar, Widget, Layout, Control Sidebar
 * Catatan: Ini bukan versi lengkap, tapi ringkasan fungsi utama
 */

(function($){

    "use strict";

    // ===============================
    // DEFAULT SETTINGS / CONFIG
    // ===============================
    const AdminLTEOptions = {
        sidebarCollapsed: false,
        navbarFixed: true,
        sidebarMini: true,
        enableControlSidebar: true,
        enableBoxWidget: true,
        animationSpeed: 300
    };

    // ===============================
    // SIDEBAR TOGGLE
    // ===============================
    function toggleSidebar() {
        $('body').toggleClass('sidebar-collapse');
        AdminLTEOptions.sidebarCollapsed = !$('body').hasClass('sidebar-collapse');
    }

    // Auto close sidebar on small screen
    function autoCollapseSidebar() {
        if ($(window).width() < 768) {
            $('body').addClass('sidebar-collapse');
        }
    }

    // ===============================
    // SIDEBAR MENU TREE
    // ===============================
    function initSidebarMenu() {
        $('.sidebar .nav-treeview').each(function() {
            const $treeview = $(this).closest('li');
            $treeview.find('> a').on('click', function(e) {
                e.preventDefault();
                $treeview.toggleClass('menu-open');
                $(this).next('.nav-treeview').slideToggle(AdminLTEOptions.animationSpeed);
            });
        });
    }

    // ===============================
    // CONTROL SIDEBAR (Panel Kanan)
    // ===============================
    function initControlSidebar() {
        if(AdminLTEOptions.enableControlSidebar) {
            $('[data-widget="control-sidebar"]').on('click', function() {
                $('.control-sidebar').toggleClass('control-sidebar-open');
            });
        }
    }

    // ===============================
    // BOX WIDGETS (Card Collapse, Remove)
    // ===============================
    function initBoxWidget() {
        if(AdminLTEOptions.enableBoxWidget) {
            // Collapse
            $(document).on('click', '[data-widget="collapse"]', function() {
                const box = $(this).closest('.card');
                box.find('.card-body, .card-footer').slideToggle(AdminLTEOptions.animationSpeed);
                box.toggleClass('collapsed-card');
            });

            // Remove
            $(document).on('click', '[data-widget="remove"]', function() {
                const box = $(this).closest('.card');
                box.slideUp(AdminLTEOptions.animationSpeed, function() {
                    box.remove();
                });
            });
        }
    }

    // ===============================
    // LAYOUT FIX HEIGHT / RESPONSIVE
    // ===============================
    function fixLayoutHeight() {
        const windowHeight = $(window).height();
        const headerHeight = $('.main-header').outerHeight() || 0;
        const footerHeight = $('.main-footer').outerHeight() || 0;
        const sidebarHeight = $('.main-sidebar').height() || 0;

        const minHeight = Math.max(windowHeight - headerHeight - footerHeight, sidebarHeight);
        $('.content-wrapper, .main-sidebar, .right-side').css('min-height', minHeight + 'px');
    }

    $(window).resize(fixLayoutHeight);
    $(document).ready(function() {
        fixLayoutHeight();
        autoCollapseSidebar();
    });

    // ===============================
    // INIT SEMUA
    // ===============================
    function init() {
        initSidebarMenu();
        initControlSidebar();
        initBoxWidget();
        fixLayoutHeight();
    }

    $(document).ready(init);

})(jQuery);
